function main(p, state) {
  function isPlanks(id) { return /^minecraft:[a-z_]+_planks$/.test(String(id)); }
  function isStick(id) { return /^minecraft:stick$/.test(String(id)); }
  function isLog(id) {
    var s = String(id);
    return /^minecraft:(stripped_)?[a-z_]+(_log|_wood|_stem|_hyphae)$/.test(s) || /^minecraft:(stripped_)?bamboo_block$/.test(s);
  }
  function allOf(list, fn) {
    if (!list || !list.length) { return false; }
    for (var k = 0; k < list.length; k++) { if (!fn(list[k])) { return false; } }
    return true;
  }
  var out = { ok: false, cells: [], needPlanks: 0, needSticks: 0, stickId: '', plankId: '' };
  var recipes = p.recipes || [];
  if (!recipes.length) { return out; }
  var r = recipes[0] || {};
  var pattern = r.pattern || [];
  var key = r.key || {};
  for (var row = 0; row < pattern.length; row++) {
    var line = String(pattern[row] || '');
    for (var col = 0; col < line.length; col++) {
      var ch = line.charAt(col);
      if (ch === ' ') { continue; }
      var list = key[ch] || [];
      if (!list.length) { return { ok: false, cells: [], needPlanks: 0, needSticks: 0, stickId: '', plankId: '' }; }
      var match;
      if (allOf(list, isPlanks)) { match = 'planks'; out.needPlanks += 1; if (!out.plankId) { out.plankId = String(list[0]); } }
      else if (allOf(list, isStick)) { match = 'stick'; out.needSticks += 1; if (!out.stickId) { out.stickId = String(list[0]); } }
      else if (allOf(list, isLog)) { match = 'log'; }
      else { match = String(list[0]); }
      out.cells.push({ slot: 1 + row * 3 + col, match: match });
    }
  }
  out.ok = out.cells.length > 0;
  return out;
}
